import re

_OTHER = re.compile(r"[^a-z0-9]+")


def slugify(title):
    lowered = "".join(ch.lower() if "A" <= ch <= "Z" else ch for ch in title)
    return _OTHER.sub("-", lowered)

def slugify(title):
    out = []
    pending = False
    for ch in title:
        if "A" <= ch <= "Z":
            ch = chr(ord(ch) + 32)
        if ("a" <= ch <= "z") or ("0" <= ch <= "9"):
            if pending and out:
                out.append("-")
            pending = False
            out.append(ch)
        else:
            pending = True
    return "".join(out)
